namespace RonSijm.FluidHumidifier.Factories.MediaTailor;

public class PrefetchScheduleFactory(string resourceName = null, Action<Humidifier.MediaTailor.PrefetchSchedule> factoryAction = null) : ResourceFactory<Humidifier.MediaTailor.PrefetchSchedule>(resourceName)
{

    internal InnerPrefetchSchedulePrefetchConsumptionFactory ConsumptionFactory { get; set; }

    internal InnerPrefetchSchedulePrefetchRetrievalFactory RetrievalFactory { get; set; }

    internal InnerPrefetchScheduleRecurringPrefetchConfigurationFactory RecurringPrefetchConfigurationFactory { get; set; }

    protected override Humidifier.MediaTailor.PrefetchSchedule Create()
    {
        var prefetchScheduleResult = CreatePrefetchSchedule();
        factoryAction?.Invoke(prefetchScheduleResult);

        return prefetchScheduleResult;
    }

    private Humidifier.MediaTailor.PrefetchSchedule CreatePrefetchSchedule()
    {
        var prefetchScheduleResult = new Humidifier.MediaTailor.PrefetchSchedule
        {
            GivenName = InputResourceName,
        };

        return prefetchScheduleResult;
    }
    public override void CreateChildren(Humidifier.MediaTailor.PrefetchSchedule result)
    {
        base.CreateChildren(result);

        result.Consumption ??= ConsumptionFactory?.Build();
        result.Retrieval ??= RetrievalFactory?.Build();
        result.RecurringPrefetchConfiguration ??= RecurringPrefetchConfigurationFactory?.Build();
    }

} // End Of Class

